    }
    assert.equal((await taskRequest(`${otherTaskPath}/${firstTask.id}`, 'PATCH', { title: 'Wrong project' })).status, 404);
    const renamedTask = await taskRequest(`${taskPath}/${firstTask.id}`, 'PATCH', { title: '  Renamed completed task  ' });
